unsigned flac_process_audio_loop(SF_PRIVATE *psf, unsigned len)
{
    unsigned total_bytes_processed = 0;
    unsigned bytes_read = 0;

    if (psf == NULL || len == 0)
        return 0;

    // Copy any already decoded data from the buffer
    if (psf->decoder.buffer_size > 0) {
        unsigned copy_len = len < psf->decoder.buffer_size ? len : psf->decoder.buffer_size;
        memcpy(psf->output_buffer, psf->decoder.buffer, copy_len);
        psf->decoder.buffer += copy_len;
        psf->decoder.buffer_size -= copy_len;
        total_bytes_processed += copy_len;
        len -= copy_len;
    }

    while (len > 0) {
        // Check the decoder state
        if (psf->decoder.state == FLAC_DECODER_ERROR) {
            SF_LOG(psf, "FLAC decoder error state encountered.");
            psf->decoder.frame = NULL;
            break;
        }

        if (psf->decoder.state == FLAC_DECODER_STREAM_END) {
            SF_LOG(psf, "FLAC stream end reached.");
            psf->decoder.frame = NULL;
            break;
        }

        // Simulate reading and decoding additional data
        bytes_read = flac_read_and_decode(psf, psf->output_buffer + total_bytes_processed, len);
        if (bytes_read == 0) {
            SF_LOG(psf, "No more data to read from stream.");
            break;
        }

        total_bytes_processed += bytes_read;
        len -= bytes_read;
    }

    return total_bytes_processed;
}

unsigned flac_decoder_audio_loop(SF_PRIVATE *psf, unsigned len) {
    unsigned bytes_processed = 0;
    unsigned current_position = 0;
    unsigned remaining_length = len;

    while (remaining_length > 0 && psf->decoder_state != FLAC__DECODER_STATE_END_OF_STREAM) {
        if (psf->decoder_state == FLAC__DECODER_STATE_ERROR) {
            psf_log_printf(psf, "FLAC decoder in error state: %s\n", FLAC__DecoderStateString[psf->decoder_state]);
            break;
        }

        if (psf->decoded_buffer_size > 0) {
            unsigned copy_length = (psf->decoded_buffer_size < remaining_length) ? psf->decoded_buffer_size : remaining_length;
            psf->audio->data[0] = realloc(psf->audio->data[0], current_position + copy_length);
            memcpy(psf->audio->data[0] + current_position, psf->decoded_buffer, copy_length);
            current_position += copy_length;
            bytes_processed += copy_length;
            remaining_length -= copy_length;
            psf->decoded_buffer_size = 0;
            continue;
        }

        // Decode additional data
        unsigned decoded_bytes = flac_decode_next_block(psf, remaining_length);
        if (decoded_bytes == 0) {
            break;
        }

        bytes_processed += decoded_bytes;
        remaining_length -= decoded_bytes;

        // Continue decoding if not yet reaching the requested length
    }

    if (psf->decoder_state == FLAC__DECODER_STATE_END_OF_STREAM || psf->decoder_state == FLAC__DECODER_STATE_ERROR) {
        psf_log_printf(psf, "FLAC stream ended or in error state: %s\n", FLAC__DecoderStateString[psf->decoder_state]);
        psf->frame = NULL;
    }

    return bytes_processed;
}

unsigned flac_process_audio_data(SF_PRIVATE *psf, unsigned len) {
    unsigned bytes_processed = 0;
    unsigned int pos = 0;
    unsigned int read_len;

    if (psf == NULL || len == 0)
        return 0;

    if (psf->flac_decoder == NULL)
        return 0;

    if (psf->flac_decoder->buffer_used > 0) {
        read_len = (psf->flac_decoder->buffer_used < len) ? psf->flac_decoder->buffer_used : len;
        psf->flac_decoder->buffer_used -= read_len;
        bytes_processed += read_len;
    }

    while (bytes_processed < len) {
        if (psf->flac_decoder->state == FLAC__DECODER_READ_STATUS_ERROR) {
            psf_log_printf(psf, "FLAC decoder error: %s\n", FLAC__StreamDecoderStateString[psf->flac_decoder->state]);
            psf->flac_decoder->frame = NULL;
            break;
        }

        if (psf->flac_decoder->state == FLAC__STREAM_DECODER_END_OF_STREAM) {
            psf_log_printf(psf, "End of FLAC stream reached.\n");
            psf->flac_decoder->frame = NULL;
            break;
        }

        read_len = len - bytes_processed;
        psf->flac_decoder->bytes_read = read_len;
        if (psf->flac_decoder->read_func(psf, psf->flac_decoder->input_buffer, &read_len) != SF_ERR_NO_ERROR) {
            psf_log_printf(psf, "Error reading FLAC stream data.\n");
            break;
        }

        bytes_processed += read_len;
    }

    return bytes_processed;
}

unsigned process_flac_audio_data(SF_PRIVATE *psf, unsigned len)
{
    unsigned pos = 0;
    unsigned bytes_processed = 0;

    if (psf == NULL || len == 0)
        return 0;

    if (psf->decoder_state == FLAC__STREAM_DECODER_STATE_ERROR) {
        SF_LOG_ERROR("FLAC decoder is in error state.");
        return 0;
    }

    if (psf->buffer_pos > 0) {
        unsigned copy_len = SF_MIN(len, psf->buffer_pos);
        memcpy(psf->output + pos, psf->buffer, copy_len);
        pos += copy_len;
        psf->buffer_pos -= copy_len;
        bytes_processed += copy_len;
    }

    while (pos < len) {
        if (psf->decoder_state != FLAC__STREAM_DECODER_STATE_DECODING) {
            SF_LOG_ERROR("FLAC decoder state is not in decoding mode.");
            break;
        }

        unsigned read_len = SF_MIN(len - pos, psf->frame_size);
        if (psf->frame == NULL || psf->frame_size == 0) {
            SF_LOG_ERROR("FLAC frame is null or has zero size.");
            break;
        }

        memcpy(psf->output + pos, psf->frame, read_len);
        pos += read_len;
        bytes_processed += read_len;

        if (psf->decoder_state == FLAC__STREAM_DECODER_STATE_END_OF_STREAM) {
            SF_LOG_INFO("End of FLAC stream reached.");
            psf->frame = NULL;
            break;
        }
    }

    if (psf->decoder_state == FLAC__STREAM_DECODER_STATE_ERROR) {
        SF_LOG_ERROR("Error occurred during FLAC decoding.");
        psf->frame = NULL;
    }

    return bytes_processed;
}
